/// `joining_type`
pub(crate) fn joining_type(u: u32) -> u8 {
    match u >> 12 {
        0x0 => {
            if (0x0600..=0x08E2).contains(&u) {
                return joining_table[(u - 0x0600) as usize + joining_offset_0x0600u];
            }
        }
        0x1 => {
            if (0x1806..=0x18AA).contains(&u) {
                return joining_table[(u - 0x1806) as usize + joining_offset_0x1806u];
            }
        }
        0x2 => {
            if (0x200C..=0x2069).contains(&u) {
                return joining_table[(u - 0x200C) as usize + joining_offset_0x200cu];
            }
        }
        0xA => {
            if (0xA840..=0xA873).contains(&u) {
                return joining_table[(u - 0xA840) as usize + joining_offset_0xa840u];
            }
        }
        0x10 => {
            if (0x10AC0..=0x10AEF).contains(&u) {
                return joining_table[(u - 0x10AC0) as usize + joining_offset_0x10ac0u];
            }
            if (0x10B80..=0x10BAF).contains(&u) {
                return joining_table[(u - 0x10B80) as usize + joining_offset_0x10b80u];
            }
            if (0x10D00..=0x10D23).contains(&u) {
                return joining_table[(u - 0x10D00) as usize + joining_offset_0x10d00u];
            }
            if (0x10F30..=0x10FCB).contains(&u) {
                return joining_table[(u - 0x10F30) as usize + joining_offset_0x10f30u];
            }
        }
        0x11 => {
            if (0x110BD..=0x110CD).contains(&u) {
                return joining_table[(u - 0x110BD) as usize + joining_offset_0x110bdu];
            }
        }
        0x1E => {
            if (0x1E900..=0x1E94B).contains(&u) {
                return joining_table[(u - 0x1E900) as usize + joining_offset_0x1e900u];
            }
        }
        _ => {}
    }
    X
}

